create table public.resume_versions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,role_slug text not null,content jsonb not null,version integer not null,created_at timestamptz not null default now(),unique(user_id,title,version));
create table public.profile_share_links(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,resume_version_id uuid references public.resume_versions(id),token_hash text not null unique,visible_sections text[] not null,expires_at timestamptz not null,revoked_at timestamptz,max_views integer,view_count integer not null default 0,created_at timestamptz not null default now());
create table public.profile_share_views(id bigint generated always as identity primary key,share_link_id uuid not null references public.profile_share_links(id) on delete cascade,viewer_fingerprint_hash text,viewed_at timestamptz not null default now());
alter table public.resume_versions enable row level security;alter table public.profile_share_links enable row level security;alter table public.profile_share_views enable row level security;create policy "users manage resumes" on public.resume_versions for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "users manage share links" on public.profile_share_links for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "users read share views" on public.profile_share_views for select using(exists(select 1 from public.profile_share_links l where l.id=share_link_id and l.user_id=auth.uid()));create index active_share_links_idx on public.profile_share_links(token_hash,expires_at) where revoked_at is null;
